 public function read(string$today,array$filters):array
 {
  if(!$this->validDate($today))throw new \RuntimeException('Directory clock unavailable.');$catalog=$this->processPrefix.'fm2_workforce_catalog';$orders=$this->processPrefix.'fm2_assignment_orders';$members=$this->processPrefix.'fm2_order_installers';$cases=$this->processPrefix.'fm2_installation_cases';$objects=$this->legacyPrefix.'fm_maintable';
  $latest=(new Query())->addSelect(['installation_case_id','version_no'=>new Expression('MAX([[version_no]])')])->from($orders)->groupBy('installation_case_id');
  $active=(new Query())->addSelect(['installer_tab_id'=>'oi.installer_tab_id'])->distinct()->from(['oi'=>$members])->innerJoin(['ao'=>$orders],'ao.id=oi.assignment_order_id')->innerJoin(['latest'=>$latest],'latest.installation_case_id=ao.installation_case_id AND latest.version_no=ao.version_no')->where(['ao.status'=>'registered'])->andWhere(['<>','oi.change_action','release'])->andWhere(['<=','oi.valid_from',$today])->andWhere(['or',['oi.valid_to'=>null],['>=','oi.valid_to',$today]]);
