  $condition=['and',['w.reconciliation_state'=>'delivered']];if($filters['status']!=='')$condition[]=['w.employment_status'=>$filters['status']];if($filters['availability']!==''){$correlated=(clone$active)->andWhere(new Expression('[[oi.installer_tab_id]]=[[w.installer_tab_id]]'));$condition[]=[$filters['availability']==='assigned'?'exists':'not exists',$correlated];}if($filters['q']!==''){$search=['or',['like','w.fio',$filters['q']]];if($filters['tab']!=='')$search[]=['like',new Expression('CAST([[w.installer_tab_id]] AS CHAR)'),$filters['tab']];$condition[]=$search;}
  $total=(int)(new Query())->from(['w'=>$catalog])->where($condition)->count('*',$this->db);$pages=max(1,(int)ceil($total/self::PAGE_SIZE));if($filters['page']>$pages)throw new \OutOfRangeException('Directory page unavailable.');
