  if($ids!==[]){$assignmentRows=(new Query())->addSelect(['oi.installer_tab_id','ao.registration_number','object_id'=>'c.legacy_installation_object_id','address'=>'o.ordadr_address','oi.valid_from'])->from(['oi'=>$members])->innerJoin(['ao'=>$orders],'ao.id=oi.assignment_order_id')->innerJoin(['latest'=>$latest],'latest.installation_case_id=ao.installation_case_id AND latest.version_no=ao.version_no')->innerJoin(['c'=>$cases],'c.id=ao.installation_case_id')->innerJoin(['o'=>$objects],'o.id=c.legacy_installation_object_id')->where(['oi.installer_tab_id'=>$ids,'ao.status'=>'registered'])->andWhere(['<>','oi.change_action','release'])->andWhere(['<=','oi.valid_from',$today])->andWhere(['or',['oi.valid_to'=>null],['>=','oi.valid_to',$today]])->orderBy(['oi.installer_tab_id'=>SORT_ASC,'oi.valid_from'=>SORT_ASC,'c.legacy_installation_object_id'=>SORT_ASC])->all($this->db);foreach($assignmentRows as$assignment){$this->validateAssignment($assignment);$assignments[(int)$assignment['installer_tab_id']][]=$assignment;}}
  foreach($rows as&$row){$this->validateInstaller($row);$row['assignments']=$assignments[(int)$row['installer_tab_id']]??[];}unset($row);$totalCatalog=(int)($summary['total']??0);$working=(int)($summary['working']??0);return['summary'=>['total'=>$totalCatalog,'working'=>$working,'dismissed'=>$totalCatalog-$working,'assigned'=>(int)($summary['assigned']??0),'updatedAt'=>$summary['updated_at']],'rows'=>$rows,'filters'=>$filters+['total'=>$total,'pages'=>$pages]];
 }
 private function validateInstaller(array$row):void{if((int)($row['installer_tab_id']??0)<1||trim((string)($row['fio']??''))===''||trim((string)($row['position']??''))===''||!in_array($row['employment_status']??null,['employed','dismissed'],true)||!$this->validTimestamp((string)($row['workforce_source_updated_at']??''))||(($row['dismissal_effective_at']??null)!==null&&!$this->validDate((string)$row['dismissal_effective_at'])))throw new \RuntimeException('Directory row unavailable.');}
 private function validateAssignment(array$row):void{if((int)($row['installer_tab_id']??0)<1||(int)($row['object_id']??0)<1||trim((string)($row['registration_number']??''))===''||trim((string)($row['address']??''))===''||!$this->validDate((string)($row['valid_from']??'')))throw new \RuntimeException('Directory assignment unavailable.');}
